<script setup lang="ts">
import {computed,reactive,ref} from 'vue'
import {GitMerge,ArrowRight,CheckCheck,Handshake,Clock3} from '@lucide/vue'
import type {ApiResult,Player,RoomState} from '../types'
import type {JointLane,JointProject} from '../living-types'
import content from '../content.json'
const props=defineProps<{player:Player;state:RoomState;busy:boolean;now:number;perform:(a:string,p?:Record<string,unknown>)=>Promise<ApiResult|undefined>}>()
const option=ref('bridge-twin'),modes=reactive<Record<string,string>>({}),workers=reactive<Record<string,string>>({})
const current=computed(()=>props.state.jointResearch.projects.find(j=>!['completed','cancelled'].includes(j.status)))
const free=computed(()=>props.player.students.filter(s=>!s.graduatedAt&&s.availability.canWork))
const def=(j:JointProject)=>content.living.jointProjects.find(d=>d.id===j.option)!
const mode=(l:JointLane)=>modes[l.owner]||'self'
const money=(j:JointProject,l:JointLane)=>def(j).cost*(mode(l)==='outsource'?3:mode(l)==='equipment'?2:1)
const wait=(at?:number)=>at?Math.max(0,Math.ceil((at-props.now)/60000))+' 分钟':'等待进展'
const phase:Record<string,string>={working:'分别准备工序',integration:'两份材料已齐',integrating:'整合验证中',ready:'等待共同验收',completed:'已共同完成',cancelled:'已撤回'}
function start(j:JointProject,l:JointLane,external=false){return props.perform('joint_start',{id:j.id,owner:l.owner,mode:external?'outsource':mode(l),studentId:workers[l.owner]})}
</script>
<template><section class="joint-panel"><header class="v8-heading"><GitMerge :size="29"/><div><span class="small-label">TWO DISCIPLINES · TWO PIECES OF THE SAME PUZZLE</span><h2>各做一半，拼成同一个成果。</h2><p>智能建造负责结构与数据底图，低空方向负责航线、通信与飞行验证。分别上线也能接力。</p></div></header>
 <p v-if="state.lab.level<2" class="v8-lock">联合实验室二级开放。这里会出现双方专业工序，完成整合后共同验收分账。</p>
 <form v-else-if="!current" class="v8-form" @submit.prevent="perform('joint_open',{option})"><label>新的联合课题<select v-model="option"><option v-for="d in content.living.jointProjects" :key="d.id" :value="d.id" :disabled="state.lab.level<('level'in d?Number(d.level):2)">{{ d.name }} · 总经费 {{ d.funds }}{{ 'level'in d?' · Lv.'+d.level:'' }}</option></select></label><p class="v8-muted">放上工作台不会扣费。每项工序开工各消耗 1 行动力与支持费，整合后双方各得一半验收经费与共同经历。</p><button class="primary" :disabled="busy||Object.keys(state.players).length<2"><Handshake :size="16"/>放上联合工作台</button></form>
 <article v-if="current" class="joint-dossier"><header><span class="small-label">{{ phase[current.status] }}</span><h2>{{ current.title }}</h2><p>总验收经费 {{ def(current).funds }} · 双方各 {{ def(current).funds/2 }} · 完成后各获联合示范成果点</p></header><div class="joint-lanes"><article v-for="l in current.lanes" :key="l.owner" :class="l.role"><span class="person-label">{{ state.players[l.owner]?.name }} · {{ l.role==='civil'?'智能建造工序':'低空研究工序' }}</span><h3>{{ l.deliverable }}</h3>
   <template v-if="l.status==='available'&&l.owner===player.id"><label>准备方式<select :value="mode(l)" @change="modes[l.owner]=($event.target as HTMLSelectElement).value"><option value="self">我自己推进 · 基准 {{ def(current).hours }} 小时</option><option value="student">请学生参与 · 按实际研究节奏</option><option value="equipment" :disabled="!player.assets.some(a=>a.mode==='research')">使用科研资产 · 3 小时</option><option value="outsource">经费外协 · 2 小时</option></select></label><label v-if="mode(l)==='student'">参与同学<select v-model="workers[l.owner]"><option value="">选择本组空闲同学</option><option v-for="s in free" :key="s.id" :value="s.id">{{ s.name }} · {{ s.moodText }}</option></select></label><p class="v8-muted">支出 {{ money(current,l) }} 经费，学生参与会分走个人研究精力。</p><button class="primary" :disabled="busy||player.energy<1||player.funds<money(current,l)||mode(l)==='student'&&!workers[l.owner]||['self','equipment'].includes(mode(l))&&!!(player.worldWork||player.contractWork)" @click="start(current,l)">安排这一工序<ArrowRight :size="15"/></button></template>
   <template v-else-if="l.status==='available'"><p class="v8-muted">搭子可以晚点选择自己的安排。也可以由你承担这项工序的外协费继续推进，不占用对方时间或经费。</p><button class="secondary" :disabled="busy||player.energy<1||player.funds<def(current).cost*3" @click="start(current,l,true)">我承担外协 · {{ def(current).cost*3 }} 经费</button></template>
   <template v-else-if="l.status==='working'"><p><Clock3 :size="15"/>{{ l.stalled?'还在等新的研究材料':'预计 '+wait(l.dueAt)+' 后备齐' }}</p><p v-if="l.studentName">{{ l.studentName }}参与准备</p><div class="progress-track"><i :style="{width:(l.progressPercent||0)+'%'}"/></div><button v-if="l.owner===player.id&&l.studentId" class="secondary" :disabled="busy||!!player.worldWork||!!player.contractWork" @click="perform('joint_takeover',{id:current.id})">老师接手，保留已有材料</button></template><p v-else class="v8-success"><CheckCheck :size="17"/>材料已放上工作台，等另一份一起整合。</p>
  </article></div>
  <div v-if="current.status==='integration'" class="joint-integration"><h3>两份材料齐了，最后怎样整合？</h3><p>都能完成有效交付。补充交叉复核会花费更多时间与经费，也得到更完整的研究材料和声望。</p><button class="primary" :disabled="busy||player.funds<100" @click="perform('joint_integrate',{id:current.id,choice:'verify'})">交叉复核 · 100 经费 · 3 小时</button><button class="secondary" :disabled="busy" @click="perform('joint_integrate',{id:current.id,choice:'demonstrate'})">先做边界明确的示范 · 免费 · 1 小时</button></div><p v-if="current.status==='integrating'" class="v8-muted">两份专业材料正在整合，预计 {{ wait(current.dueAt) }} 后可以验收。</p><button v-if="current.status==='ready'" class="primary wide" :disabled="busy" @click="perform('joint_claim',{id:current.id})"><CheckCheck :size="17"/>共同验收，按约定各领一半</button><button v-if="current.host===player.id&&current.lanes.every(l=>l.status==='available')" class="text-button" :disabled="busy" @click="perform('joint_cancel',{id:current.id})">先收起尚未开工的课题</button>
 </article><details v-if="state.jointResearch.projects.some(j=>j.status==='completed')" class="v8-history"><summary>我们一起做过的联合研究</summary><article v-for="j in [...state.jointResearch.projects].reverse().filter(j=>j.status==='completed')" :key="j.id"><h3>{{ j.title }}</h3><p>{{ j.lanes.map(l=>l.deliverable).join(' + ') }}</p><small>{{ j.completedAt?new Date(j.completedAt).toLocaleDateString('zh-CN'):'' }} · 已共同验收</small></article></details></section></template>
